7	import { randomUUID } from 'node:crypto';
8	import { EventEmitter } from 'node:events';
9	import type { PolicyEngine } from '../policy/policy-engine.js';
10	import { PolicyDecision } from '../policy/types.js';
11	import { MessageBusType, type Message } from './types.js';
12	import { safeJsonStringify } from '../utils/safeJsonStringify.js';
13	import { debugLogger } from '../utils/debugLogger.js';
14	
15	export class MessageBus extends EventEmitter {
16	  private listenerToAbortCleanup = new WeakMap<
17	    object,
18	    Map<string, () => void>
19	  >();
20	
21	  constructor(
22	    private readonly policyEngine: PolicyEngine,
23	    private readonly debug = false,
24	  ) {
25	    super();
26	    this.debug = debug;
27	  }
28	
29	  private isValidMessage(message: Message): boolean {
30	    if (!message || !message.type) {
31	      return false;
32	    }
33	
34	    if (
35	      message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST &&
36	      !('correlationId' in message)
37	    ) {
38	      return false;
39	    }
40	
41	    return true;
42	  }
43	
44	  private emitMessage(message: Message): void {
45	    this.emit(message.type, message);
46	  }
47	
48	  /**
49	   * Derives a child message bus scoped to a specific subagent.
50	   */
51	  derive(subagentName: string): MessageBus {
52	    const bus = new MessageBus(this.policyEngine, this.debug);
53	
54	    bus.publish = async (message: Message) => {
55	      if (message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST) {
56	        return this.publish({
57	          ...message,
58	          subagent: message.subagent
59	            ? `${subagentName}/${message.subagent}`
60	            : subagentName,
61	        });
62	      }
63	      return this.publish(message);
64	    };
65	
66	    // Delegate subscription methods to the parent bus
67	    bus.subscribe = this.subscribe.bind(this);
68	    bus.unsubscribe = this.unsubscribe.bind(this);
69	    bus.on = this.on.bind(this);
70	    bus.off = this.off.bind(this);
71	    bus.emit = this.emit.bind(this);
72	    bus.once = this.once.bind(this);
73	    bus.removeListener = this.removeListener.bind(this);
74	    bus.listenerCount = this.listenerCount.bind(this);
75	
76	    return bus;
77	  }
78	
79	  async publish(message: Message): Promise<void> {
80	    if (this.debug) {
81	      debugLogger.debug(`[MESSAGE_BUS] publish: ${safeJsonStringify(message)}`);
82	    }
83	    try {
84	      if (!this.isValidMessage(message)) {
85	        throw new Error(
86	          `Invalid message structure: ${safeJsonStringify(message)}`,
87	        );
88	      }
89	
90	      if (message.type === MessageBusType.TOOL_CONFIRMATION_REQUEST) {
91	        const { decision: policyDecision } = await this.policyEngine.check(
92	          message.toolCall,
93	          message.serverName,
94	          message.toolAnnotations,
95	          message.subagent,
96	        );
97	
98	        const decision = message.forcedDecision ?? policyDecision;
99	
100	        switch (decision) {
101	          case PolicyDecision.ALLOW:
102	            // Directly emit the response instead of recursive publish
103	            this.emitMessage({
104	              type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
105	              correlationId: message.correlationId,
106	              confirmed: true,
107	            });
108	            break;
109	          case PolicyDecision.DENY:
110	            // Emit both rejection and response messages
111	            this.emitMessage({
112	              type: MessageBusType.TOOL_POLICY_REJECTION,
113	              toolCall: message.toolCall,
114	            });
115	            this.emitMessage({
116	              type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
117	              correlationId: message.correlationId,
118	              confirmed: false,
119	            });
120	            break;
121	          case PolicyDecision.ASK_USER:
122	            // Pass through to UI for user confirmation if any listeners exist.
123	            // If no listeners are registered (e.g., headless/ACP flows),
124	            // immediately request user confirmation to avoid long timeouts.
125	            if (
126	              this.listenerCount(MessageBusType.TOOL_CONFIRMATION_REQUEST) > 0
127	            ) {
128	              this.emitMessage(message);
129	            } else {
130	              this.emitMessage({
131	                type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
132	                correlationId: message.correlationId,
133	                confirmed: false,
134	                requiresUserConfirmation: true,
135	              });
136	            }
137	            break;
138	          default:
139	            throw new Error(`Unknown policy decision: ${decision}`);
140	        }
141	      } else {
142	        // For all other message types, just emit them
143	        this.emitMessage(message);
144	      }
145	    } catch (error) {
146	      this.emit('error', error);
147	    }
148	  }
149	
150	  subscribe<T extends Message>(
151	    type: T['type'],
152	    listener: (message: T) => void,
153	    options?: { signal?: AbortSignal },
154	  ): void {
155	    if (options?.signal) {
156	      const signal = options.signal;
157	      if (signal.aborted) return;
158	
159	      if (this.listenerToAbortCleanup.get(listener)?.has(type)) return;
160	
161	      const abortHandler = () => {
162	        this.off(type, listener);
163	        const typeToCleanup = this.listenerToAbortCleanup.get(listener);
164	        if (typeToCleanup) {
165	          typeToCleanup.delete(type);
166	          if (typeToCleanup.size === 0) {
167	            this.listenerToAbortCleanup.delete(listener);
168	          }
169	        }
170	      };
171	      signal.addEventListener('abort', abortHandler, { once: true });
172	
173	      let typeToCleanup = this.listenerToAbortCleanup.get(listener);
174	      if (!typeToCleanup) {
175	        typeToCleanup = new Map<string, () => void>();
176	        this.listenerToAbortCleanup.set(listener, typeToCleanup);
177	      }
178	      typeToCleanup.set(type, () => {
179	        signal.removeEventListener('abort', abortHandler);
180	      });
181	    }
182	
183	    this.on(type, listener);
184	  }
185	
186	  unsubscribe<T extends Message>(
187	    type: T['type'],
188	    listener: (message: T) => void,
189	  ): void {
190	    this.off(type, listener);
191	    const typeToCleanup = this.listenerToAbortCleanup.get(listener);
192	    if (typeToCleanup) {
193	      const cleanup = typeToCleanup.get(type);
194	      if (cleanup) {
195	        cleanup();
196	        typeToCleanup.delete(type);
197	      }
198	      if (typeToCleanup.size === 0) {
199	        this.listenerToAbortCleanup.delete(listener);
200	      }
201	    }
202	  }
203	
204	  /**
205	   * Request-response pattern: Publish a message and wait for a correlated response
206	   * This enables synchronous-style communication over the async MessageBus
207	   * The correlation ID is generated internally and added to the request
208	   */
209	  async request<TRequest extends Message, TResponse extends Message>(
210	    request: Omit<TRequest, 'correlationId'>,
211	    responseType: TResponse['type'],
212	    timeoutMs: number = 60000,
213	  ): Promise<TResponse> {
214	    const correlationId = randomUUID();
215	
216	    return new Promise<TResponse>((resolve, reject) => {
217	      const timeoutId = setTimeout(() => {
218	        cleanup();
219	        reject(new Error(`Request timed out waiting for ${responseType}`));
220	      }, timeoutMs);
221	
222	      const cleanup = () => {
223	        clearTimeout(timeoutId);
224	        this.unsubscribe(responseType, responseHandler);
225	      };
226	
