110	      };
111	      expect(rejectionHandler).toHaveBeenCalledWith(expectedRejection);
112	
113	      const expectedResponse: ToolConfirmationResponse = {
114	        type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
115	        correlationId: '123',
