117	      };
118	      expect(responseHandler).toHaveBeenCalledWith(expectedResponse);
119	    });
120	
121	    it('should pass through to UI when policy says ASK_USER', async () => {
122	      vi.spyOn(policyEngine, 'check').mockResolvedValue({
123	        decision: PolicyDecision.ASK_USER,
