133	        type: MessageBusType.TOOL_CONFIRMATION_REQUEST,
134	        toolCall: { name: 'test-tool', args: {} },
135	        correlationId: '123',
136	      };
137	
138	      await messageBus.publish(request);
139	
140	      expect(requestHandler).toHaveBeenCalledWith(request);
