162	        annotations,
163	        undefined,
164	      );
165	    });
166	
167	    it('should emit other message types directly', async () => {
168	      const successHandler = vi.fn();
169	      messageBus.subscribe(
170	        MessageBusType.TOOL_EXECUTION_SUCCESS,
171	        successHandler,
172	      );
173	
174	      const message: ToolExecutionSuccess<string> = {
175	        type: MessageBusType.TOOL_EXECUTION_SUCCESS as const,
176	        toolCall: { name: 'test-tool' },
