184	  });
185	
186	  describe('subscribe/unsubscribe', () => {
187	    it('should allow subscribing to specific message types', async () => {
188	      const handler = vi.fn();
189	      messageBus.subscribe(MessageBusType.TOOL_EXECUTION_SUCCESS, handler);
190	
191	      const message: ToolExecutionSuccess<string> = {
192	        type: MessageBusType.TOOL_EXECUTION_SUCCESS as const,
193	        toolCall: { name: 'test' },
194	        result: 'test',
195	      };
196	
197	      await messageBus.publish(message);
198	
199	      expect(handler).toHaveBeenCalledWith(message);
