201	
202	    it('should allow unsubscribing from message types', async () => {
203	      const handler = vi.fn();
204	      messageBus.subscribe(MessageBusType.TOOL_EXECUTION_SUCCESS, handler);
205	      messageBus.unsubscribe(MessageBusType.TOOL_EXECUTION_SUCCESS, handler);
206	
