205	        queueVisibleEvent(event);
206	      }
207	
208	      while (true) {
209	        if (eventQueue.length > 0) {
210	          const eventsToYield = eventQueue;
211	          eventQueue = [];
212	          for (const event of eventsToYield) {
213	            yield event;
214	          }
215	          continue;
216	        }
217	
218	        if (done) break;
219	        await next;
220	      }
221	    } finally {
222	      unsubscribe();
223	    }
