136	
137	  dispose(): void {
138	    coreEvents.off(CoreEvent.McpProgress, this.handleMcpProgress);
139	    this.disposeController.abort();
140	  }
141	
142	  private readonly handleMcpProgress = (payload: McpProgressPayload) => {
143	    const { callId } = payload;
144	
145	    const call = this.state.getToolCall(callId);
146	    if (!call || call.status !== CoreToolCallStatus.Executing) {
147	      return;
148	    }
149	
150	    const validTotal =
151	      payload.total !== undefined &&
152	      Number.isFinite(payload.total) &&
153	      payload.total > 0
154	        ? payload.total
155	        : undefined;
156	
157	    this.state.updateStatus(callId, CoreToolCallStatus.Executing, {
158	      progressMessage: payload.message,
159	      progressPercent: validTotal
160	        ? Math.min(100, (payload.progress / validTotal) * 100)
161	        : undefined,
162	      progress: payload.progress,
163	      progressTotal: validTotal,
164	    });
165	  };
166	
167	  private readonly handleToolConfirmationRequest = async (
168	    request: ToolConfirmationRequest,
169	  ) => {
170	    await this.messageBus.publish({
171	      type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
172	      correlationId: request.correlationId,
173	      confirmed: false,
174	      requiresUserConfirmation: true,
175	    });
176	  };
177	
178	  private setupMessageBusListener(messageBus: MessageBus): void {
179	    // TODO: Optimize policy checks. Currently, tools check policy via
180	    // MessageBus even though the Scheduler already checked it.
181	    messageBus.subscribe(
182	      MessageBusType.TOOL_CONFIRMATION_REQUEST,
183	      this.handleToolConfirmationRequest,
184	      { signal: this.disposeController.signal },
185	    );
186	  }
187	
188	  /**
189	   * Schedules a batch of tool calls.
190	   * @returns A promise that resolves with the results of the completed batch.
191	   */
192	  async schedule(
193	    request: ToolCallRequestInfo | ToolCallRequestInfo[],
194	    signal: AbortSignal,
195	  ): Promise<CompletedToolCall[]> {
196	    return runInDevTraceSpan(
197	      {
198	        operation: GeminiCliOperation.ScheduleToolCalls,
199	        logPrompts: this.context.config.getTelemetryLogPromptsEnabled(),
200	        tracesEnabled: this.context.config.getTelemetryTracesEnabled(),
201	        sessionId: this.context.config.getSessionId(),
202	      },
203	      async ({ metadata: spanMetadata }) => {
204	        const requests = Array.isArray(request) ? request : [request];
205	
206	        spanMetadata.input = requests;
207	
208	        let toolCallResponse: CompletedToolCall[] = [];
209	
210	        if (this.isProcessing || this.state.isActive) {
211	          toolCallResponse = await this._enqueueRequest(requests, signal);
212	        } else {
213	          toolCallResponse = await this._startBatch(requests, signal);
214	        }
215	
216	        spanMetadata.output = toolCallResponse;
217	        return toolCallResponse;
218	      },
219	    );
220	  }

